import {CAMERAS,environmentAt,cameraEnvironment,nearbyContacts} from './environment.js';
const tm=t=>String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');
export function radarSvg(s){const contacts=nearbyContacts(s);return `<svg class="radar-plot" viewBox="0 0 100 100" role="img" aria-label="周圍兩百公尺內 ${contacts.reduce((n,c)=>n+c.people,0)} 個人員訊號"><circle class="radar-range" cx="50" cy="50" r="44"/><circle class="radar-range" cx="50" cy="50" r="22"/><path class="radar-axis" d="M50 6v88M6 50h88"/><path class="radar-road" d="m80 5-11 27-17 18-15 38"/><g class="radar-sweep"><path d="M50 50 50 6A44 44 0 0 1 81 19Z"/></g><path class="radar-origin" d="m50 46 4 7h-8Z"/>${contacts.map(c=>`<g class="radar-contact ${c.known?'known':'unverified'}" transform="translate(${c.x} ${c.y})"><circle r="3"/><title>${c.label}，約 ${c.distance} 公尺，${c.motion}</title>${c.people>1?'<circle cx="6" cy="3" r="2"/>':''}</g>`).join('')}</svg>`;}
export function smallMap(s){const rooms=[['dorm','寢室',5,4],['gate','門禁',67,4],['canteen','餐廳',5,54],['engineering','工程',67,54]];return `<svg class="small-map" viewBox="0 0 120 94" role="img" aria-label="庇護所小地圖，實心點是你的位置"><path class="map-corridor" d="M5 41h110v10H5z M56 4h8v85h-8z"/>${rooms.map(([id,name,x,y])=>`<g><rect class="map-room ${s.location===id?'map-current':''}" x="${x}" y="${y}" width="48" height="34"/><text x="${x+24}" y="${y+22}">${name}</text>${s.location===id?`<circle class="map-player" cx="${x+7}" cy="${y+7}" r="3"/>`:''}</g>`).join('')}</svg>`;}
export function radarHud(s){const cs=nearbyContacts(s),approach=cs.find(c=>c.id==='approach-01');return `<button class="radar-hud" data-ui="cameras" aria-label="開啟地圖、雷達與監視器"><span class="radar-heading">小地圖 · 附近偵測 <span>200 m</span></span>${radarSvg(s)}${smallMap(s)}<span class="radar-summary">${approach?`${approach.people} 人 · 約 ${approach.distance} m · ${approach.motion}`:cs.length?'巡檢同事在附近':'附近沒有接近訊號'}</span><span class="radar-link">切換監視器 →</span></button>`;}
export function shelterMap(s,selected){const pos={dorm:[74,53],canteen:[103,122],gate:[230,57],engineering:[247,149]}[s.location]||[230,57],cam=CAMERAS.find(c=>c.id===selected)||CAMERAS[0];return `<svg class="shelter-map" viewBox="0 0 340 205" role="img" aria-label="庇護所區域圖，目前在${{dorm:'寢室',canteen:'餐廳',gate:'門禁',engineering:'工程'}[s.location]}，正在看${cam.name}"><path class="map-corridor" d="M28 83h284v25H28z M172 28h22v151h-22z"/><path class="map-room" d="M28 20h128v63H28z M28 108h128v69H28z M209 20h103v63H209z M209 108h103v69H209z"/><path class="map-entry" d="M312 41h23v24h-23"/><text x="91" y="47">生活區</text><text x="91" y="139">公共餐廳</text><text x="261" y="46">門禁</text><text x="261" y="139">工程區</text><circle class="map-camera" cx="${cam.map[0]}" cy="${cam.map[1]}" r="13"/><circle class="map-player" cx="${pos[0]}" cy="${pos[1]}" r="5"/><text class="map-legend" x="28" y="197">實心點：你的位置　圓框：目前鏡頭</text></svg>`;}
export function cameraPanel(s,{header,c,esc},camera='gate',preview='live'){
 const cam=CAMERAS.find(c=>c.id===camera)||CAMERAS[0],env=cameraEnvironment(s,preview),cs=nearbyContacts(s),live=preview==='live';
 header('看看庇護所內外','SURVEILLANCE');
 c.innerHTML=`<div class="monitor-layout"><section class="camera-console"><nav class="camera-tabs" aria-label="選擇監視器">${CAMERAS.map(cam=>`<button data-camera="${cam.id}" class="${cam.id===camera?'selected':''}" aria-pressed="${cam.id===camera}">${cam.code.slice(0,6)}<span>${cam.name}</span></button>`).join('')}</nav><div class="camera-feed phase-${env.phase} weather-${env.kind} ${cam.id==='hall'?'camera-hall':''}" style="--scene-art:url('${env.art}');--camera-position:${cam.position}"><div class="camera-picture"></div><div class="camera-osd"><span>${cam.code}</span><span>${live?'值勤畫面':'時段預覽'} · ${tm(env.time)}</span></div><span class="camera-bottom">${esc(cam.note)}<br>${env.phaseName} · ${env.label} · ${env.temperature}°C</span></div><div class="camera-controls"><label for="camera-preview">查看時段</label><select id="camera-preview" class="field" data-camera-preview><option value="live" ${live?'selected':''}>現在 · 跟著遊戲時間</option>${[['dawn','清晨 06:50'],['day','白天 10:30'],['rain','雨天 14:00'],['dusk','傍晚 17:30'],['night','夜間 20:30']].map(([k,label])=>`<option value="${k}" ${preview===k?'selected':''}>預覽：${label}</option>`).join('')}</select></div><p class="monitor-note">${live?'畫面依目前遊戲時間與天候顯示。查看監視器時，值勤時鐘暫停。':'這是光線與天候預覽，不會改變現在時間、人員位置或任務。'}鏡頭使用場景示意；人員位置以雷達目前時間為準。</p></section><aside class="monitor-side"><section><h3>庇護所區域示意</h3>${shelterMap(s,camera)}</section><section class="monitor-radar"><h3>附近人員 <span>目前 ${tm(s.time)}</span></h3>${radarSvg(s)}<ul class="contact-list">${cs.length?cs.map(co=>`<li><span class="contact-mark ${co.known?'known':'unverified'}"></span><div><strong>${esc(co.label)}</strong><span>約 ${co.distance} m · ${co.motion}</span></div><small>${co.known?'識別已知':'待查核'}</small></li>`).join(''):'<li>目前沒有接近訊號。</li>'}</ul><p class="monitor-note">偵測範圍 200 m。圓點表示已知識別；空心點表示待查核。位置訊號不能代替身分與健康驗證。</p></section></aside></div>`;
}
